insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('6da66f01-8a52-4744-965b-b0ebfa20433d', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', null, 'topic'::public.curated_course_node_type, 'Health Professions Landscape and Career Families', 'This opening section helps students see healthcare as a large ecosystem rather than a single career ladder. The goal is to build a mental map of who does what, where different professions overlap, and how career families contribute to patient and population health.', 0),
  ('0427c9c5-eff5-48bd-8f1a-740732c3b7f2', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '6da66f01-8a52-4744-965b-b0ebfa20433d', 'subtopic'::public.curated_course_node_type, 'Healthcare Career Families and Professional Domains', 'Students learn the major categories of health professions so they can compare roles with a shared vocabulary instead of relying on stereotypes or job titles alone.', 0),
  ('bef0ee51-d467-4d25-904e-8ad856a3613a', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '0427c9c5-eff5-48bd-8f1a-740732c3b7f2', 'concept'::public.curated_course_node_type, 'Clinical care; diagnostic services; therapeutic services; health informatics; public health; health administration; research; community health', null, 0),
  ('c9e1fada-63eb-423a-b6b0-bb92dff9ea3d', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '0427c9c5-eff5-48bd-8f1a-740732c3b7f2', 'concept'::public.curated_course_node_type, 'Primary care; specialty care; acute care; rehabilitation; behavioral health; long-term care; emergency care; preventive care', null, 1),
  ('f767d9d7-cae0-495a-ac69-4b83d5efc5a5', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '0427c9c5-eff5-48bd-8f1a-740732c3b7f2', 'concept'::public.curated_course_node_type, 'Direct patient care roles; indirect patient care roles; technical roles; population-facing roles; leadership and management roles', null, 2),
  ('bcaaa211-9a99-4f16-9726-82a77dddacf3', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '0427c9c5-eff5-48bd-8f1a-740732c3b7f2', 'concept'::public.curated_course_node_type, 'Entry-level, associate, bachelor''s, master''s, doctoral, residency, fellowship, and continuing education pathways', null, 3),
  ('3cb30dce-ddb5-4284-a7dc-1052a65d40c3', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '6da66f01-8a52-4744-965b-b0ebfa20433d', 'subtopic'::public.curated_course_node_type, 'Healthcare Workforce Needs and Labor Market Signals', 'This subtopic connects personal career interest to real workforce demand, helping students read occupational data and understand why certain roles are expanding.', 1),
  ('6b5dda0f-9e52-49d7-876b-1649d48e1b8a', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '3cb30dce-ddb5-4284-a7dc-1052a65d40c3', 'concept'::public.curated_course_node_type, 'Workforce shortages; aging population; chronic disease burden; rural and underserved-area need; behavioral health access gaps', null, 0),
  ('bbf78b99-6e30-4444-8f6e-bef3ff0a06c1', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '3cb30dce-ddb5-4284-a7dc-1052a65d40c3', 'concept'::public.curated_course_node_type, 'BLS job outlook; median pay; projected growth; geographic variation; education requirements; working conditions', null, 1),
  ('9076fc40-3486-444f-98ba-13db90d0c08f', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '3cb30dce-ddb5-4284-a7dc-1052a65d40c3', 'concept'::public.curated_course_node_type, 'Burnout, retention, pipeline programs, workforce diversity, loan repayment, and service obligations', null, 2),
  ('8089af7e-c3a8-4d07-8868-9d6e709e049a', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '3cb30dce-ddb5-4284-a7dc-1052a65d40c3', 'concept'::public.curated_course_node_type, 'New roles in care coordination, population health, telehealth, data analytics, and community-based care', null, 3),
  ('6971f1d7-2cc6-4df2-9653-9ec91d56948f', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '6da66f01-8a52-4744-965b-b0ebfa20433d', 'subtopic'::public.curated_course_node_type, 'How Professions Contribute to Patient and Population Outcomes', 'Students examine how different roles affect outcomes, cost, experience, access, and safety so career choice is tied to impact, not just tasks.', 2),
  ('330dc204-d4b5-4ea4-a3ac-bc3413fac1f3', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '6971f1d7-2cc6-4df2-9653-9ec91d56948f', 'concept'::public.curated_course_node_type, 'Patient outcomes; patient experience; access to care; care continuity; prevention; health equity; cost and value', null, 0),
  ('d149d087-a9a3-4d2a-a7b2-b00fec3a365d', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '6971f1d7-2cc6-4df2-9653-9ec91d56948f', 'concept'::public.curated_course_node_type, 'Clinical decision-making, patient education, diagnostic accuracy, medication safety, rehabilitation progress, and care transitions', null, 1),
  ('51bae15e-e490-43be-933b-dc275967e141', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '6971f1d7-2cc6-4df2-9653-9ec91d56948f', 'concept'::public.curated_course_node_type, 'Community health workers, navigators, social workers, public health practitioners, and health educators in population outcomes', null, 2),
  ('8d938b7a-0cc5-4c1d-85c0-005c088176df', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '6971f1d7-2cc6-4df2-9653-9ec91d56948f', 'concept'::public.curated_course_node_type, 'Quality metrics, safety indicators, readmission rates, preventive screening rates, and patient-reported outcomes', null, 3),
  ('1b7f2e38-d290-4d96-ae95-443dbb7f43a0', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', null, 'topic'::public.curated_course_node_type, 'Medical, Nursing, Allied Health, Behavioral Health, Public Health, and Administrative Roles', 'This section makes the profession map more concrete. Students compare everyday responsibilities, training demands, practice environments, and collaboration points across the central clusters of healthcare work.', 1),
  ('8a92894f-d007-4d24-ab2f-9b6d2c275a37', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '1b7f2e38-d290-4d96-ae95-443dbb7f43a0', 'subtopic'::public.curated_course_node_type, 'Medical and Advanced Practice Roles', 'Students learn how physicians, physician assistants, nurse practitioners, and related clinicians diagnose, treat, prescribe, coordinate care, and carry accountability in different settings.', 0),
  ('cd340ee5-96cf-4170-9b19-822b088d1a4a', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '8a92894f-d007-4d24-ab2f-9b6d2c275a37', 'concept'::public.curated_course_node_type, 'Physician, physician assistant, nurse practitioner, clinical nurse specialist, certified nurse midwife, certified registered nurse anesthetist', null, 0),
  ('64dd295c-4152-46e3-a104-b8df08ab0a92', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '8a92894f-d007-4d24-ab2f-9b6d2c275a37', 'concept'::public.curated_course_node_type, 'Diagnosis; differential diagnosis; treatment planning; prescribing; ordering tests; referrals; clinical documentation', null, 1),
  ('4ec0beb7-53bd-4929-8b31-2a3712793a07', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '8a92894f-d007-4d24-ab2f-9b6d2c275a37', 'concept'::public.curated_course_node_type, 'Medical school, PA school, graduate nursing, residency, fellowship, board certification, maintenance of certification', null, 2),
  ('7b55b563-495c-442d-bda3-dddd074d2e49', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '8a92894f-d007-4d24-ab2f-9b6d2c275a37', 'concept'::public.curated_course_node_type, 'Generalist versus specialist roles; supervision models; collaborative practice agreements; scope-of-practice variation by state', null, 3),
  ('b14d6906-5875-48f6-9321-53bab8158577', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '1b7f2e38-d290-4d96-ae95-443dbb7f43a0', 'subtopic'::public.curated_course_node_type, 'Nursing, Allied Health, and Technical Professions', 'This subtopic highlights the breadth of essential care roles that keep health systems functioning at the bedside, in clinics, in labs, and in rehabilitation environments.', 1),
  ('804d3d8d-4383-426e-8a9a-8da19058246d', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'b14d6906-5875-48f6-9321-53bab8158577', 'concept'::public.curated_course_node_type, 'Registered nurse; licensed practical nurse; medical assistant; respiratory therapist; physical therapist; occupational therapist; speech-language pathologist', null, 0),
  ('e4c8fe37-45cc-422c-be81-3f8f0891cc3c', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'b14d6906-5875-48f6-9321-53bab8158577', 'concept'::public.curated_course_node_type, 'Radiologic technologist; sonographer; clinical laboratory scientist; pharmacy technician; dental hygienist; dietitian; paramedic', null, 1),
  ('90e0c145-bd39-4c0c-b219-e8a30c43a6bc', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'b14d6906-5875-48f6-9321-53bab8158577', 'concept'::public.curated_course_node_type, 'Assessment, monitoring, medication administration, imaging, laboratory testing, therapy plans, nutrition counseling, and emergency response', null, 2),
  ('f9df7b9b-6165-4c54-850b-e65106bd6c92', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'b14d6906-5875-48f6-9321-53bab8158577', 'concept'::public.curated_course_node_type, 'Certification exams, clinical hours, supervised practice, competency checkoffs, specialty credentials, and continuing education', null, 3),
  ('ebf9c72e-b80b-4fc2-a049-1b44ffb6e5e7', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '1b7f2e38-d290-4d96-ae95-443dbb7f43a0', 'subtopic'::public.curated_course_node_type, 'Behavioral Health, Public Health, and Administrative Careers', 'Students broaden their view beyond clinical treatment to roles that address mental health, community health, program operations, policy, finance, and organizational leadership.', 2),
  ('ea31c4f3-a1ce-437d-b9c7-507b1dade80f', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'ebf9c72e-b80b-4fc2-a049-1b44ffb6e5e7', 'concept'::public.curated_course_node_type, 'Psychologist; counselor; social worker; psychiatric nurse; substance-use counselor; case manager; community health worker', null, 0),
  ('7275fa0d-926d-49c2-8209-6825e80f8d82', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'ebf9c72e-b80b-4fc2-a049-1b44ffb6e5e7', 'concept'::public.curated_course_node_type, 'Epidemiologist; health educator; public health analyst; environmental health specialist; emergency preparedness coordinator', null, 1),
  ('67807536-4edd-4277-91c6-e93dbd10ffff', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'ebf9c72e-b80b-4fc2-a049-1b44ffb6e5e7', 'concept'::public.curated_course_node_type, 'Healthcare administrator; practice manager; revenue cycle analyst; health information manager; quality improvement specialist', null, 2),
  ('74e423f6-9bab-4141-ba84-0c681d19d473', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'ebf9c72e-b80b-4fc2-a049-1b44ffb6e5e7', 'concept'::public.curated_course_node_type, 'Program planning, population surveillance, benefits navigation, patient advocacy, scheduling, compliance, budgeting, and strategic planning', null, 3),
  ('3507b4d9-6b55-444d-a3e2-0f4dac2eda5c', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', null, 'topic'::public.curated_course_node_type, 'Education Pathways, Admissions, Licensure, Certification, and Scope of Practice', 'This section turns career interest into a realistic academic plan. Students learn how prerequisites, admissions, clinical experiences, exams, licensure, certification, and legal scope shape entry into health professions.', 2),
  ('7233e31f-f116-4b22-9675-d4b551b7d4ff', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '3507b4d9-6b55-444d-a3e2-0f4dac2eda5c', 'subtopic'::public.curated_course_node_type, 'Academic Pathways and Prerequisite Planning', 'Students identify the courses, experiences, timelines, and preparation habits needed to apply competitively to different health professional programs.', 0),
  ('3ff4f9cb-db86-4393-8f8b-f9be0f998efd', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '7233e31f-f116-4b22-9675-d4b551b7d4ff', 'concept'::public.curated_course_node_type, 'Prerequisite sciences; anatomy and physiology; chemistry; microbiology; psychology; statistics; medical terminology; ethics', null, 0),
  ('ca1bed8b-d35d-4685-a92d-b9bf2c5a5e1a', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '7233e31f-f116-4b22-9675-d4b551b7d4ff', 'concept'::public.curated_course_node_type, 'Shadowing, volunteering, direct patient care hours, research, service learning, leadership, and community engagement', null, 1),
  ('070b51a5-e6fe-416b-a461-11d312174825', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '7233e31f-f116-4b22-9675-d4b551b7d4ff', 'concept'::public.curated_course_node_type, 'Application timelines; centralized applications; letters of recommendation; personal statements; interviews; prerequisite expiration rules', null, 2),
  ('53d9a145-c4a3-4d66-a00f-c169fae2a29d', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '7233e31f-f116-4b22-9675-d4b551b7d4ff', 'concept'::public.curated_course_node_type, 'GPA planning, course sequencing, retakes, transfer credits, clinical observation requirements, and program accreditation checks', null, 3),
  ('b86bebfd-4ffb-4bb2-8bb6-20d7b66730fe', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '3507b4d9-6b55-444d-a3e2-0f4dac2eda5c', 'subtopic'::public.curated_course_node_type, 'Licensure, Certification, Credentialing, and Privileging', 'Students learn the difference between earning a degree and being authorized to practice, which is essential for understanding professional accountability.', 1),
  ('512ff7ee-42fe-4867-aa51-71788cba2786', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'b86bebfd-4ffb-4bb2-8bb6-20d7b66730fe', 'concept'::public.curated_course_node_type, 'Licensure; certification; registration; credentialing; privileging; board certification; continuing competence', null, 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('86b57e97-f674-4a5e-81c3-15f0a757b4e8', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'b86bebfd-4ffb-4bb2-8bb6-20d7b66730fe', 'concept'::public.curated_course_node_type, 'State boards; national certifying bodies; background checks; jurisprudence exams; renewal cycles; continuing education units', null, 1),
  ('add7a19a-9041-4a69-bfb0-5b3788e8182c', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'b86bebfd-4ffb-4bb2-8bb6-20d7b66730fe', 'concept'::public.curated_course_node_type, 'Clinical privileges, institutional policies, malpractice coverage, disciplinary action, and license portability', null, 2),
  ('09ca91d3-aef7-43ae-8907-27842d8f9a8c', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'b86bebfd-4ffb-4bb2-8bb6-20d7b66730fe', 'concept'::public.curated_course_node_type, 'Examples: NCLEX, USMLE, PANCE, NREMT, ASCP, ARRT, RD exam, PT board exam, OT board exam', null, 3),
  ('d31140ee-4f45-471c-bc3d-70f9a279ae52', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '3507b4d9-6b55-444d-a3e2-0f4dac2eda5c', 'subtopic'::public.curated_course_node_type, 'Scope of Practice and Delegation', 'This subtopic teaches students how teams divide work safely and legally, especially when tasks overlap across professions.', 2),
  ('5b44df3c-1cb4-404d-b186-27820fe3b457', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'd31140ee-4f45-471c-bc3d-70f9a279ae52', 'concept'::public.curated_course_node_type, 'Scope of practice; standard of care; delegation; supervision; competency; accountability; task authority', null, 0),
  ('5da78abc-3700-4ea0-8da6-4547c6fa2c6d', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'd31140ee-4f45-471c-bc3d-70f9a279ae52', 'concept'::public.curated_course_node_type, 'Independent, dependent, and collaborative functions; standing orders; protocols; escalation pathways', null, 1),
  ('0c4d9d18-5907-40be-9e06-fc197a63e217', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'd31140ee-4f45-471c-bc3d-70f9a279ae52', 'concept'::public.curated_course_node_type, 'State variation, institutional policy, professional standards, liability, and documentation of delegated tasks', null, 2),
  ('4cbd7744-53e4-4c97-9a19-7cde68143597', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'd31140ee-4f45-471c-bc3d-70f9a279ae52', 'concept'::public.curated_course_node_type, 'Role confusion, inappropriate delegation, practicing beyond scope, and escalation when patient safety is at risk', null, 3),
  ('b12f2076-bc02-44b8-80e2-0ecec2fdbb47', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', null, 'topic'::public.curated_course_node_type, 'Professional Identity, Ethics, Boundaries, and Accountability', 'This section establishes the moral and professional foundation of health careers. Students learn that competence includes judgment, humility, honesty, confidentiality, respect, and accountability under pressure.', 3),
  ('6268042e-1b65-462d-a2a7-7f9e8bfd1474', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'b12f2076-bc02-44b8-80e2-0ecec2fdbb47', 'subtopic'::public.curated_course_node_type, 'Core Principles of Healthcare Ethics', 'Students use major ethical principles to reason through common dilemmas in patient care, research, and organizational decision-making.', 0),
  ('a06dc832-1ad4-4f3f-ac2f-121889eafb2a', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '6268042e-1b65-462d-a2a7-7f9e8bfd1474', 'concept'::public.curated_course_node_type, 'Autonomy; beneficence; nonmaleficence; justice; veracity; fidelity; dignity; respect for persons', null, 0),
  ('14f66bea-0c72-4145-838d-11d680806ab2', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '6268042e-1b65-462d-a2a7-7f9e8bfd1474', 'concept'::public.curated_course_node_type, 'Informed consent, decision-making capacity, substituted judgment, assent, refusal of treatment, and shared decision-making', null, 1),
  ('a91de378-36d6-4acb-989c-8e2efaafa4c8', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '6268042e-1b65-462d-a2a7-7f9e8bfd1474', 'concept'::public.curated_course_node_type, 'Resource allocation, triage, conflicts of interest, dual loyalty, moral distress, and conscientious objection', null, 2),
  ('321de4be-c4f6-472f-b804-95a763ab7556', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '6268042e-1b65-462d-a2a7-7f9e8bfd1474', 'concept'::public.curated_course_node_type, 'Ethical case analysis: facts, stakeholders, values, options, consequences, professional duties, and documentation', null, 3),
  ('e7905a03-2183-4be4-80c9-0ef18f511bd3', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'b12f2076-bc02-44b8-80e2-0ecec2fdbb47', 'subtopic'::public.curated_course_node_type, 'Professionalism, Boundaries, and Codes of Conduct', 'Students learn the behavioral expectations that make patients and colleagues able to trust healthcare professionals.', 1),
  ('db58b990-d7ba-4048-8dec-02d078082fd1', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'e7905a03-2183-4be4-80c9-0ef18f511bd3', 'concept'::public.curated_course_node_type, 'Professional identity; accountability; reliability; punctuality; honesty; respectful communication; appearance; follow-through', null, 0),
  ('f77d5263-1756-4dc7-a9b5-efe60a92471e', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'e7905a03-2183-4be4-80c9-0ef18f511bd3', 'concept'::public.curated_course_node_type, 'Boundary management, social media conduct, conflicts of interest, gifts, romantic boundaries, and power differences', null, 1),
  ('5651c589-b705-414a-85a1-199eb955dfe0', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'e7905a03-2183-4be4-80c9-0ef18f511bd3', 'concept'::public.curated_course_node_type, 'Professional codes, institutional policies, reporting obligations, impairment, harassment, and discrimination', null, 2),
  ('e644067e-9385-4447-a223-1b426e7c2e96', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'e7905a03-2183-4be4-80c9-0ef18f511bd3', 'concept'::public.curated_course_node_type, 'Mistake disclosure, apology, documentation, peer concern reporting, and responding to feedback', null, 3),
  ('26de1420-bbc0-4614-8689-c986e6b9632a', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'b12f2076-bc02-44b8-80e2-0ecec2fdbb47', 'subtopic'::public.curated_course_node_type, 'Confidentiality, Trust, and Fiduciary Responsibility', 'This subtopic explains why healthcare work creates special duties: patients reveal personal information and depend on professionals at vulnerable moments.', 2),
  ('ea3d8d1d-f0b9-47cc-b661-73857b1af5e9', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '26de1420-bbc0-4614-8689-c986e6b9632a', 'concept'::public.curated_course_node_type, 'Fiduciary duty; privacy; confidentiality; minimum necessary information; need-to-know access; duty to warn', null, 0),
  ('2f7475af-9c66-4753-a6ab-378773cecc54', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '26de1420-bbc0-4614-8689-c986e6b9632a', 'concept'::public.curated_course_node_type, 'Confidentiality exceptions: abuse reporting, communicable disease reporting, imminent harm, court orders, and public health law', null, 1),
  ('ec679ec1-21c6-4954-ab25-0524764694e5', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '26de1420-bbc0-4614-8689-c986e6b9632a', 'concept'::public.curated_course_node_type, 'Trust-building behaviors, transparency, consistency, cultural respect, and reliability in follow-up', null, 2),
  ('74fbf17a-1441-4d5a-8aff-e64a99db732a', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '26de1420-bbc0-4614-8689-c986e6b9632a', 'concept'::public.curated_course_node_type, 'Professional accountability to patients, families, teams, employers, licensing boards, and communities', null, 3),
  ('2ac3e4ba-e196-412b-8575-e805671a5a39', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', null, 'topic'::public.curated_course_node_type, 'Patient-Centered Care, Communication, Health Literacy, and Patient Education', 'Healthcare begins with human communication. This section gives students practical language, listening skills, and teaching strategies that support understanding, dignity, safety, and shared decisions.', 4),
  ('4591cfff-ca1f-4bf1-9ef1-f7fb9678a4bf', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '2ac3e4ba-e196-412b-8575-e805671a5a39', 'subtopic'::public.curated_course_node_type, 'Therapeutic Communication and Active Listening', 'Students practice communication behaviors that help patients feel heard while giving clinicians accurate information for safe care.', 0),
  ('2ca55613-6256-4158-b8ac-9afef37dea71', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '4591cfff-ca1f-4bf1-9ef1-f7fb9678a4bf', 'concept'::public.curated_course_node_type, 'Open-ended questions; reflective listening; empathy statements; silence; summarizing; normalization; validation', null, 0),
  ('427ecc46-667d-4581-a132-aa9d9d7d032b', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '4591cfff-ca1f-4bf1-9ef1-f7fb9678a4bf', 'concept'::public.curated_course_node_type, 'Chief concern, history-taking basics, ICE framework, agenda setting, signposting, and closing the loop', null, 1),
  ('0a70ec24-0a4a-4dcd-8206-2ef983ff47fe', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '4591cfff-ca1f-4bf1-9ef1-f7fb9678a4bf', 'concept'::public.curated_course_node_type, 'Nonverbal communication, tone, eye contact, physical positioning, privacy, and emotionally charged conversations', null, 2),
  ('5289e4e8-ff39-404a-9632-9c9afd618d83', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '4591cfff-ca1f-4bf1-9ef1-f7fb9678a4bf', 'concept'::public.curated_course_node_type, 'Difficult conversations, de-escalation, responding to anger, grief, fear, stigma, and uncertainty', null, 3),
  ('c6dd2856-8980-4abf-a1c9-748dd95d93a2', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '2ac3e4ba-e196-412b-8575-e805671a5a39', 'subtopic'::public.curated_course_node_type, 'Health Literacy and Patient Education', 'Students learn that patient understanding cannot be assumed, and that clear education is a safety skill.', 1),
  ('7dfce0a8-84cd-4928-8b8d-92a2d239ec62', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'c6dd2856-8980-4abf-a1c9-748dd95d93a2', 'concept'::public.curated_course_node_type, 'Health literacy; numeracy; plain language; teach-back; chunk-and-check; visual aids; translation versus interpretation', null, 0),
