  ('8487a95c-e998-40b0-9dac-fec079c9ce5f', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'c6dd2856-8980-4abf-a1c9-748dd95d93a2', 'concept'::public.curated_course_node_type, 'Readability, cultural relevance, accessibility, disability accommodations, and digital literacy', null, 2),
  ('2d2d1666-3d77-4cd6-a84a-5de664ac2dc8', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'c6dd2856-8980-4abf-a1c9-748dd95d93a2', 'concept'::public.curated_course_node_type, 'Patient goals, barriers, readiness to change, motivational interviewing basics, and behavior-change support', null, 3),
  ('eda0a449-7c7a-42ff-8ba6-f143fe606d52', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '2ac3e4ba-e196-412b-8575-e805671a5a39', 'subtopic'::public.curated_course_node_type, 'Shared Decision-Making and Patient Experience', 'Students examine how respectful care includes patient values, preferences, lived experience, and practical constraints.', 2),
  ('9f594ab3-1b25-4c17-a5e8-c4e1bc69830a', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'eda0a449-7c7a-42ff-8ba6-f143fe606d52', 'concept'::public.curated_course_node_type, 'Shared decision-making; preference-sensitive care; decision aids; risks and benefits; patient values clarification', null, 0),
