  ('83cff738-b07a-4200-88b4-f3d50f2d61f6', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'eda0a449-7c7a-42ff-8ba6-f143fe606d52', 'concept'::public.curated_course_node_type, 'Family and caregiver involvement, consent for sharing information, caregiver burden, and care partner education', null, 2),
  ('ade259d3-2800-4c0a-9c29-bd627ae8e81e', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'eda0a449-7c7a-42ff-8ba6-f143fe606d52', 'concept'::public.curated_course_node_type, 'Respectful language, person-first language, trauma-informed communication, and avoiding blame or stigma', null, 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('ec4fb22b-2903-47e3-a48a-17b791832a85', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', null, 'topic'::public.curated_course_node_type, 'Cultural Humility, Health Equity, Social Determinants of Health, and Access', 'This section teaches students to recognize health as shaped by more than biology. Students examine how social conditions, bias, access barriers, and structural inequities affect care and outcomes.', 5),
  ('84e522eb-7416-4953-9526-c6b6c2b693b9', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'ec4fb22b-2903-47e3-a48a-17b791832a85', 'subtopic'::public.curated_course_node_type, 'Cultural Humility and Bias Awareness', 'Students move beyond memorizing cultural facts toward ongoing self-reflection, respectful curiosity, and attention to power differences.', 0),
  ('f87fe0d7-8130-4518-9c81-ce0184eedaf1', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '84e522eb-7416-4953-9526-c6b6c2b693b9', 'concept'::public.curated_course_node_type, 'Cultural humility; cultural competence; implicit bias; structural bias; stereotyping; microaggressions', null, 0),
  ('a57c4620-363b-4920-ad40-45e4675fb178', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '84e522eb-7416-4953-9526-c6b6c2b693b9', 'concept'::public.curated_course_node_type, 'Language access, professional interpreters, religious needs, disability culture, LGBTQ+ inclusive care, and migrant health concerns', null, 1),
  ('d2846899-eef7-4c08-941d-1d6c78341327', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '84e522eb-7416-4953-9526-c6b6c2b693b9', 'concept'::public.curated_course_node_type, 'Self-reflection, power dynamics, asking respectfully, avoiding assumptions, and repairing communication missteps', null, 2),
  ('bc95aa24-6088-4c25-8ee6-91195ea99b7d', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '84e522eb-7416-4953-9526-c6b6c2b693b9', 'concept'::public.curated_course_node_type, 'Culturally responsive patient education, dietary considerations, family decision-making norms, and trust in institutions', null, 3),
  ('a7ea22e7-7e4e-4ab0-8853-779b7b672e7a', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'ec4fb22b-2903-47e3-a48a-17b791832a85', 'subtopic'::public.curated_course_node_type, 'Social Determinants of Health and Access Barriers', 'Students learn to identify nonmedical factors that influence whether patients can follow care plans and achieve good outcomes.', 1),
  ('a2c8d014-7e7e-4851-a50e-97951212a183', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'a7ea22e7-7e4e-4ab0-8853-779b7b672e7a', 'concept'::public.curated_course_node_type, 'Housing, food security, transportation, income, education, employment, neighborhood safety, environment, and social support', null, 0),
