  ('651df123-ae55-403a-975e-12dbb5de5322', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'a7ea22e7-7e4e-4ab0-8853-779b7b672e7a', 'concept'::public.curated_course_node_type, 'Screening tools, referral workflows, community resources, closed-loop referrals, and resource navigation', null, 2),
  ('be8eea75-ad56-4974-a71b-b6230fc14196', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'a7ea22e7-7e4e-4ab0-8853-779b7b672e7a', 'concept'::public.curated_course_node_type, 'Rural health, urban underserved communities, disability access, health professional shortage areas, and medically underserved areas', null, 3),
  ('74e275d5-3315-4119-9e7a-2fe775e59cab', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'ec4fb22b-2903-47e3-a48a-17b791832a85', 'subtopic'::public.curated_course_node_type, 'Health Disparities, Equity Metrics, and Justice-Oriented Practice', 'This subtopic connects ethical commitments to measurable disparities and concrete improvement strategies.', 2),
  ('3c1b72de-3aa1-4690-8d23-1d8d64bf727e', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '74e275d5-3315-4119-9e7a-2fe775e59cab', 'concept'::public.curated_course_node_type, 'Morbidity, mortality, prevalence, incidence, life expectancy, maternal mortality, infant mortality, and avoidable hospitalization gaps', null, 0),
