  ('e27dd84a-06bf-4397-8e4f-9c536479c76b', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '74e275d5-3315-4119-9e7a-2fe775e59cab', 'concept'::public.curated_course_node_type, 'Stratified quality data, equity dashboards, community needs assessments, and disparity reduction goals', null, 2),
  ('c3848dae-ef77-4a1e-b6fe-96c2a25e9ef5', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '74e275d5-3315-4119-9e7a-2fe775e59cab', 'concept'::public.curated_course_node_type, 'Equity-informed communication, anti-stigma practice, community partnership, advocacy, and policy change', null, 3),
  ('ea7321fb-96f9-470f-97b8-9f8b9ae1de7e', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', null, 'topic'::public.curated_course_node_type, 'Interprofessional Collaboration, Team Roles, SBAR, Huddles, and Handoffs', 'Modern healthcare is team-based. This section teaches students the core routines and language that make teams safer, clearer, and more coordinated.', 6),
  ('d71e6b03-337c-46eb-b9c4-3c0a8265a3d4', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'ea7321fb-96f9-470f-97b8-9f8b9ae1de7e', 'subtopic'::public.curated_course_node_type, 'Interprofessional Competencies and Team Roles', 'Students learn why role clarity and mutual respect are essential for safe care across disciplines.', 0),
  ('23e1c968-1e92-44c8-b601-9f39cc4387d0', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'd71e6b03-337c-46eb-b9c4-3c0a8265a3d4', 'concept'::public.curated_course_node_type, 'IPEC values and ethics, roles and responsibilities, interprofessional communication, teams and teamwork', null, 0),
