  ('3dcc52a4-301f-4256-a6eb-93e2c4013792', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'd71e6b03-337c-46eb-b9c4-3c0a8265a3d4', 'concept'::public.curated_course_node_type, 'Patient, family, physician, nurse, pharmacist, therapist, social worker, case manager, and administrator as team members', null, 2),
  ('f4e70040-85d1-4630-9328-e70fff25014d', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'd71e6b03-337c-46eb-b9c4-3c0a8265a3d4', 'concept'::public.curated_course_node_type, 'Team conflict, psychological safety, closed-loop communication, speaking up, and graded assertiveness', null, 3),
  ('513ca1b7-4f3b-4b72-b86a-531fa1f0c5fe', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'ea7321fb-96f9-470f-97b8-9f8b9ae1de7e', 'subtopic'::public.curated_course_node_type, 'Team Communication Tools', 'Students practice standardized communication formats that reduce ambiguity during routine and urgent care.', 1),
  ('eb35ea0b-98ce-4cc4-b846-5f94840978db', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '513ca1b7-4f3b-4b72-b86a-531fa1f0c5fe', 'concept'::public.curated_course_node_type, 'SBAR: situation, background, assessment, recommendation', null, 0),
