  ('48d27996-deb1-4ad4-b902-ccd21b5bc5ba', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '513ca1b7-4f3b-4b72-b86a-531fa1f0c5fe', 'concept'::public.curated_course_node_type, 'Critical results communication, escalation chains, rapid response activation, and safety concerns', null, 2),
  ('ec49c795-3d8b-487d-9763-d032a2aa4324', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '513ca1b7-4f3b-4b72-b86a-531fa1f0c5fe', 'concept'::public.curated_course_node_type, 'Documentation handoffs, shift change, discharge handoff, warm handoff, and electronic handoff tools', null, 3),
  ('c304f45c-8e0b-4553-9bc2-eebe58016ba6', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'ea7321fb-96f9-470f-97b8-9f8b9ae1de7e', 'subtopic'::public.curated_course_node_type, 'Care Coordination and Transitions of Care', 'This subtopic shows how coordination failures create harm and how teams support continuity across settings.', 2),
