  ('0a2a6f12-8285-4552-ba16-3fd9d6a87b7b', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'c304f45c-8e0b-4553-9bc2-eebe58016ba6', 'concept'::public.curated_course_node_type, 'Closed-loop referrals, care navigation, case management, social work coordination, and outcome tracking', null, 3),
