  ('b5118285-61c7-4e1e-a719-f2c01fd4f3ca', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '58b3996d-1f78-4f74-9afc-3f29a23fd1a5', 'subtopic'::public.curated_course_node_type, 'Acute, Emergency, and Inpatient Care', 'Students learn how hospitals organize high-acuity care, diagnostics, procedures, monitoring, and transitions.', 0),
