  ('13723add-e093-4724-93ec-c3c58f95de0c', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'b5118285-61c7-4e1e-a719-f2c01fd4f3ca', 'concept'::public.curated_course_node_type, 'Acuity, vital signs, clinical deterioration, rapid response teams, infection prevention, and hospital-acquired conditions', null, 2),
  ('fd748ef1-f584-46b3-8400-0f1040957583', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'b5118285-61c7-4e1e-a719-f2c01fd4f3ca', 'concept'::public.curated_course_node_type, 'Hospitalists, nurses, therapists, pharmacists, case managers, social workers, technicians, and environmental services', null, 3),
  ('78781fd5-d91b-437c-ad5c-2297e9a7eb30', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '58b3996d-1f78-4f74-9afc-3f29a23fd1a5', 'subtopic'::public.curated_course_node_type, 'Ambulatory, Primary Care, Specialty, and Community-Based Care', 'This subtopic shows how much healthcare happens outside hospitals, often through prevention, chronic care, and ongoing relationships.', 1),
  ('082e50d9-2cf0-4aec-ab2a-18d225c384c0', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '78781fd5-d91b-437c-ad5c-2297e9a7eb30', 'concept'::public.curated_course_node_type, 'Primary care, specialty clinics, urgent care, federally qualified health centers, school-based clinics, retail clinics, mobile clinics', null, 0);
