  ('4a6858cd-cb53-4c98-9215-b1d917546693', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '78781fd5-d91b-437c-ad5c-2297e9a7eb30', 'concept'::public.curated_course_node_type, 'Panel management, registries, patient portals, appointment scheduling, prior authorization, and population outreach', null, 2),
  ('d350975d-f6c9-45cd-9069-b9d307f225d5', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '78781fd5-d91b-437c-ad5c-2297e9a7eb30', 'concept'::public.curated_course_node_type, 'Community health workers, public health nurses, home visitors, health educators, and care navigators', null, 3),
  ('65ecd568-de3b-4195-bb76-6b5313c3c0ac', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '58b3996d-1f78-4f74-9afc-3f29a23fd1a5', 'subtopic'::public.curated_course_node_type, 'Long-Term, Rehabilitation, Hospice, and Home-Based Care', 'Students examine care settings focused on function, independence, comfort, chronic needs, and support outside acute episodes.', 2),
  ('c6bc8f19-628b-4d86-a206-3d92e01cfc0d', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '65ecd568-de3b-4195-bb76-6b5313c3c0ac', 'concept'::public.curated_course_node_type, 'Skilled nursing facility, assisted living, rehabilitation hospital, home health, hospice, palliative care, adult day programs', null, 0),
  ('1f9a68ac-1a65-4096-a59a-060aafabb5f7', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '65ecd568-de3b-4195-bb76-6b5313c3c0ac', 'concept'::public.curated_course_node_type, 'Activities of daily living, instrumental activities of daily living, fall risk, caregiver support, functional goals, and advance care planning', null, 1),
  ('51d36f32-a584-444f-87db-49c088d1dd2f', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '65ecd568-de3b-4195-bb76-6b5313c3c0ac', 'concept'::public.curated_course_node_type, 'Rehabilitation plans, durable medical equipment, wound care, medication management, home safety, and telemonitoring', null, 2),
  ('09be6023-0c33-4f57-881b-9838496a8d0a', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '65ecd568-de3b-4195-bb76-6b5313c3c0ac', 'concept'::public.curated_course_node_type, 'Continuity, dignity, comfort, caregiver education, interdisciplinary care conferences, and transitions back to community living', null, 3),
  ('c6815c06-60b7-49cd-a1fe-22942dbda958', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', null, 'topic'::public.curated_course_node_type, 'U.S. Healthcare System Structure, Financing, Insurance, Medicare, Medicaid, and ACA', 'This section gives students a practical map of how U.S. healthcare is organized and paid for. The goal is not policy mastery, but enough systems literacy to understand access, cost, and administrative realities.', 8),
  ('9b75bc23-d3c7-4a51-9d74-b4b772ff8b9d', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'c6815c06-60b7-49cd-a1fe-22942dbda958', 'subtopic'::public.curated_course_node_type, 'System Structure and Major Stakeholders', 'Students identify the organizations and actors that shape healthcare delivery, payment, regulation, and patient experience.', 0),
  ('b995e032-c862-43c9-9216-bfe48a172fe3', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '9b75bc23-d3c7-4a51-9d74-b4b772ff8b9d', 'concept'::public.curated_course_node_type, 'Patients, providers, hospitals, insurers, employers, government agencies, pharmaceutical firms, device companies, accrediting bodies', null, 0),
  ('43c951ea-5941-4ade-93fd-04837910a63b', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '9b75bc23-d3c7-4a51-9d74-b4b772ff8b9d', 'concept'::public.curated_course_node_type, 'Public sector, private sector, nonprofit systems, investor-owned systems, integrated delivery networks, accountable care organizations', null, 1),
  ('9b39c007-afa2-4393-9537-4a56137e0698', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '9b75bc23-d3c7-4a51-9d74-b4b772ff8b9d', 'concept'::public.curated_course_node_type, 'CMS, CDC, FDA, NIH, state health departments, state licensing boards, Joint Commission, NCQA, and professional associations', null, 2),
  ('01f55a7b-8454-44e0-aa64-7b9d49397c00', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '9b75bc23-d3c7-4a51-9d74-b4b772ff8b9d', 'concept'::public.curated_course_node_type, 'Fragmentation, consolidation, vertical integration, access networks, referral systems, and market power', null, 3),
  ('aa95ae41-4d7f-4fd3-8c04-087e2e695877', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'c6815c06-60b7-49cd-a1fe-22942dbda958', 'subtopic'::public.curated_course_node_type, 'Insurance, Payment, and Cost', 'This subtopic explains the everyday financial mechanisms that affect patients, clinicians, and organizations.', 1),
  ('fd187f08-a04e-4db0-a962-2b927b5363a1', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'aa95ae41-4d7f-4fd3-8c04-087e2e695877', 'concept'::public.curated_course_node_type, 'Premium, deductible, copayment, coinsurance, out-of-pocket maximum, formulary, network, prior authorization', null, 0),
  ('842988cc-560c-4bd6-8251-0321f877692d', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'aa95ae41-4d7f-4fd3-8c04-087e2e695877', 'concept'::public.curated_course_node_type, 'Fee-for-service, capitation, bundled payments, diagnosis-related groups, value-based care, pay-for-performance', null, 1),
  ('54ae83d9-fe4d-43a6-8542-99c4905a31b3', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'aa95ae41-4d7f-4fd3-8c04-087e2e695877', 'concept'::public.curated_course_node_type, 'Medicare Parts A, B, C, and D; Medicaid; CHIP; ACA marketplaces; employer-sponsored insurance; uninsured care', null, 2),
  ('31155b51-eead-4828-84bd-386f49999eb3', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'aa95ae41-4d7f-4fd3-8c04-087e2e695877', 'concept'::public.curated_course_node_type, 'Medical debt, underinsurance, cost sharing, surprise billing, price transparency, and resource stewardship', null, 3),
  ('e724656b-026e-4482-883b-f4bfc5d4d486', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'c6815c06-60b7-49cd-a1fe-22942dbda958', 'subtopic'::public.curated_course_node_type, 'Policy, Reform, and Access', 'Students learn how laws and reforms influence who receives care, how it is delivered, and what tradeoffs systems face.', 2),
  ('8d08bfac-f4ce-42cb-a185-f3274f43fbf9', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'e724656b-026e-4482-883b-f4bfc5d4d486', 'concept'::public.curated_course_node_type, 'Affordable Care Act, Medicaid expansion, EMTALA, HIPAA, parity laws, public health authority, and scope-of-practice law', null, 0),
  ('ee5c423a-1146-4e5a-ba3c-0eb6ee1cf014', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'e724656b-026e-4482-883b-f4bfc5d4d486', 'concept'::public.curated_course_node_type, 'Access, affordability, quality, equity, innovation, administrative burden, and sustainability as policy goals', null, 1),
  ('f1aedaac-6264-49ac-908e-78e2687a1401', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'e724656b-026e-4482-883b-f4bfc5d4d486', 'concept'::public.curated_course_node_type, 'International comparisons, single-payer models, multipayer systems, universal coverage, and social insurance concepts', null, 2),
  ('c48fcb87-a790-474b-8e04-05b06b6de59b', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'e724656b-026e-4482-883b-f4bfc5d4d486', 'concept'::public.curated_course_node_type, 'Advocacy, professional associations, public comment, voting, testimony, coalition-building, and ethical policy engagement', null, 3),
  ('c4c0c8f9-e4c7-4dbb-9ce5-a966dcfdd185', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', null, 'topic'::public.curated_course_node_type, 'Quality Improvement, Patient Safety, High Reliability, and Systems Thinking', 'This section introduces healthcare as a system that can be measured and improved. Students learn to look beyond individual blame and examine processes, communication, design, and culture.', 9),
  ('cf83fc2b-b165-4940-9f9c-8af36b9c16ca', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'c4c0c8f9-e4c7-4dbb-9ce5-a966dcfdd185', 'subtopic'::public.curated_course_node_type, 'Patient Safety Concepts and Error Prevention', 'Students learn how preventable harm happens and how safety science designs defenses before harm reaches patients.', 0),
  ('1e214d9b-6428-4681-ba4f-91efc56277f4', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'cf83fc2b-b165-4940-9f9c-8af36b9c16ca', 'concept'::public.curated_course_node_type, 'Adverse event, near miss, sentinel event, latent condition, active error, human factors, just culture, safety culture', null, 0),
  ('b00bf12e-59df-49b6-b455-39261bbb54be', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'cf83fc2b-b165-4940-9f9c-8af36b9c16ca', 'concept'::public.curated_course_node_type, 'Medication errors, wrong-site surgery, falls, pressure injuries, healthcare-associated infections, diagnostic error', null, 1),
  ('53b7720a-1deb-4eb0-8d35-ff5a355e796b', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'cf83fc2b-b165-4940-9f9c-8af36b9c16ca', 'concept'::public.curated_course_node_type, 'Swiss cheese model, root cause analysis, failure mode and effects analysis, checklists, forcing functions, standardization', null, 2),
  ('6ed20c74-4817-48f2-b056-847313d3e1e9', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'cf83fc2b-b165-4940-9f9c-8af36b9c16ca', 'concept'::public.curated_course_node_type, 'Incident reporting, disclosure, safety huddles, morbidity and mortality conferences, and psychological safety', null, 3),
  ('361fb579-c915-4150-ae90-d9051ef98455', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'c4c0c8f9-e4c7-4dbb-9ce5-a966dcfdd185', 'subtopic'::public.curated_course_node_type, 'Quality Improvement Methods and Measurement', 'This subtopic gives students practical improvement language for testing changes and evaluating whether care is getting better.', 1),
  ('bdeda978-a80e-4ffa-8bbc-d18f6aa5d9ad', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '361fb579-c915-4150-ae90-d9051ef98455', 'concept'::public.curated_course_node_type, 'Plan-Do-Study-Act cycles, process mapping, driver diagrams, run charts, control charts, benchmarking, and audit-feedback', null, 0),
  ('27745a4f-c37b-44ff-8be0-a99456a9e935', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '361fb579-c915-4150-ae90-d9051ef98455', 'concept'::public.curated_course_node_type, 'Structure measures, process measures, outcome measures, balancing measures, and patient-reported measures', null, 1),
  ('ab067324-7103-47f0-8af3-d17f236c9f5f', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '361fb579-c915-4150-ae90-d9051ef98455', 'concept'::public.curated_course_node_type, 'Lean, Six Sigma, waste reduction, standard work, variation, bottlenecks, and workflow redesign', null, 2),
  ('fcadfd10-be1c-4b1a-8e05-fed573a6d9e5', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '361fb579-c915-4150-ae90-d9051ef98455', 'concept'::public.curated_course_node_type, 'SMART aims, baseline data, intervention testing, spread, sustainment, and unintended consequences', null, 3),
  ('698f6978-c0d9-4440-ae64-04e1afcf1bc4', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'c4c0c8f9-e4c7-4dbb-9ce5-a966dcfdd185', 'subtopic'::public.curated_course_node_type, 'High Reliability and Systems Thinking', 'Students explore why healthcare organizations borrow ideas from high-risk industries to make safety more consistent.', 2),
  ('521c9bfd-502f-4ffc-a3d1-5fb5dc67fe53', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '698f6978-c0d9-4440-ae64-04e1afcf1bc4', 'concept'::public.curated_course_node_type, 'Preoccupation with failure, reluctance to simplify, sensitivity to operations, commitment to resilience, deference to expertise', null, 0),
  ('8078d05f-e9f5-42ff-b643-8d119bca2ffd', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '698f6978-c0d9-4440-ae64-04e1afcf1bc4', 'concept'::public.curated_course_node_type, 'Systems thinking, feedback loops, handoff reliability, redundancy, situational awareness, and resilience engineering', null, 1),
  ('6a4f158c-11f8-4192-9b6e-b47512d42cf5', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '698f6978-c0d9-4440-ae64-04e1afcf1bc4', 'concept'::public.curated_course_node_type, 'TeamSTEPPS, crew resource management, checklists, simulation, drills, and escalation protocols', null, 2),
  ('accef8a9-921a-4c10-9519-b28beb950ed7', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '698f6978-c0d9-4440-ae64-04e1afcf1bc4', 'concept'::public.curated_course_node_type, 'Equity and safety, patient voice in safety, organizational learning, and leadership walkrounds', null, 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('158a15a7-898d-4caa-b5be-fdd8322e7b4d', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', null, 'topic'::public.curated_course_node_type, 'Privacy, HIPAA, Documentation, Medical Records, and Medicolegal Risk', 'This section teaches students that records and privacy are patient-care tools, not administrative afterthoughts. Accurate documentation and responsible information handling protect patients, teams, and professionals.', 10),
  ('8dc479d4-015e-4191-8997-235d5ba17d42', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '158a15a7-898d-4caa-b5be-fdd8322e7b4d', 'subtopic'::public.curated_course_node_type, 'HIPAA, Privacy, Security, and Confidentiality', 'Students learn the practical rules for handling protected health information and respecting patient privacy.', 0),
  ('19e9df96-f03f-4767-a2db-61a984ebba4c', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '8dc479d4-015e-4191-8997-235d5ba17d42', 'concept'::public.curated_course_node_type, 'Protected health information, minimum necessary standard, authorization, consent, disclosure, breach, and de-identification', null, 0),
  ('177ef220-5a01-4f24-9667-89ff7af6f1b4', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '8dc479d4-015e-4191-8997-235d5ba17d42', 'concept'::public.curated_course_node_type, 'Privacy Rule, Security Rule, electronic protected health information, access controls, passwords, encryption, audit trails', null, 1),
  ('165d896b-bcc7-42c9-abbe-06d1749fc80e', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '8dc479d4-015e-4191-8997-235d5ba17d42', 'concept'::public.curated_course_node_type, 'Incidental disclosure, hallway conversations, social media, photography, texting, patient portals, and shared devices', null, 2),
  ('9e14b0d3-5ce5-4b8a-ab81-6a539d1638df', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '8dc479d4-015e-4191-8997-235d5ba17d42', 'concept'::public.curated_course_node_type, 'Confidentiality exceptions, mandated reporting, public health reporting, subpoenas, and institutional privacy officers', null, 3),
  ('a4c5555a-54bc-4e0a-a720-ec8307a0e7b6', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '158a15a7-898d-4caa-b5be-fdd8322e7b4d', 'subtopic'::public.curated_course_node_type, 'Documentation and Medical Records', 'Students learn how clear documentation supports continuity, billing, legal accountability, and clinical reasoning.', 1),
  ('99f7caf6-80de-42ef-984c-c518ca39ff00', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'a4c5555a-54bc-4e0a-a720-ec8307a0e7b6', 'concept'::public.curated_course_node_type, 'Electronic health record, problem list, medication list, allergies, progress notes, orders, results, flowsheets, discharge summaries', null, 0),
  ('f713612e-02f7-4244-95dd-2125622254cb', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'a4c5555a-54bc-4e0a-a720-ec8307a0e7b6', 'concept'::public.curated_course_node_type, 'SOAP notes, narrative notes, charting by exception, late entries, corrections, cosignatures, and audit trails', null, 1),
  ('27f669c0-a4aa-44ff-aee2-41de7a59b87b', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'a4c5555a-54bc-4e0a-a720-ec8307a0e7b6', 'concept'::public.curated_course_node_type, 'Accuracy, timeliness, objectivity, approved abbreviations, copy-forward risks, and documentation integrity', null, 2),
  ('512b078f-d4c6-4fdb-aed1-59ed3f64c652', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'a4c5555a-54bc-4e0a-a720-ec8307a0e7b6', 'concept'::public.curated_course_node_type, 'Clinical decision support, patient portals, interoperability, health information exchange, and information blocking', null, 3),
  ('9221c7fc-12b7-4074-89b5-8c4ae8d71a92', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '158a15a7-898d-4caa-b5be-fdd8322e7b4d', 'subtopic'::public.curated_course_node_type, 'Medicolegal Risk and Professional Responsibility', 'This subtopic introduces students to the legal risks tied to communication, documentation, scope, consent, and follow-up.', 2),
  ('a65c07d5-057c-4373-8d60-4d47c706bfac', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '9221c7fc-12b7-4074-89b5-8c4ae8d71a92', 'concept'::public.curated_course_node_type, 'Standard of care, negligence, malpractice, liability, duty, breach, causation, damages, and informed consent', null, 0),
  ('4ba338dc-d3b4-4a1a-ba93-5a69dfe00785', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '9221c7fc-12b7-4074-89b5-8c4ae8d71a92', 'concept'::public.curated_course_node_type, 'Risk management, incident reporting, adverse-event disclosure, documentation of refusal, and follow-up of abnormal results', null, 1),
  ('69661e10-f208-45cb-8c32-297c787208c1', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '9221c7fc-12b7-4074-89b5-8c4ae8d71a92', 'concept'::public.curated_course_node_type, 'Scope violations, delegation errors, privacy breaches, failure to communicate, and failure to rescue', null, 2),
  ('94b6e265-1051-45b6-a702-3e63ad88da3e', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '9221c7fc-12b7-4074-89b5-8c4ae8d71a92', 'concept'::public.curated_course_node_type, 'Professional discipline, board complaints, organizational policy, malpractice insurance, and legal-ethical overlap', null, 3),
  ('aa3e9bb9-6778-48f2-9c48-2394ad917a7b', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', null, 'topic'::public.curated_course_node_type, 'Public Health, Prevention, Population Health, and Global Health', 'This section connects individual care to broader patterns of health and disease. Students learn how prevention, surveillance, community partnership, and global systems shape health outcomes.', 11),
  ('60e44c6d-776a-439e-8398-41c4b10c9064', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'aa3e9bb9-6778-48f2-9c48-2394ad917a7b', 'subtopic'::public.curated_course_node_type, 'Public Health Foundations and Prevention', 'Students learn the basic functions of public health and how prevention reduces disease burden before clinical care is needed.', 0),
  ('2aec4ed0-2c5c-4773-89ad-6fea47f533c9', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '60e44c6d-776a-439e-8398-41c4b10c9064', 'concept'::public.curated_course_node_type, 'Assessment, policy development, assurance, surveillance, outbreak response, health promotion, and emergency preparedness', null, 0),
  ('7fe3b42c-3190-4fe5-92ed-5734af744c44', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '60e44c6d-776a-439e-8398-41c4b10c9064', 'concept'::public.curated_course_node_type, 'Primary, secondary, and tertiary prevention; screening; immunization; counseling; harm reduction; environmental health', null, 1),
  ('11b45d96-966f-412d-944a-a82a91d50be4', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '60e44c6d-776a-439e-8398-41c4b10c9064', 'concept'::public.curated_course_node_type, 'Communicable disease, chronic disease, injury prevention, maternal-child health, occupational health, and mental health promotion', null, 2),
  ('4f45f87a-94e1-4492-bd8b-c9c8b70ce626', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '60e44c6d-776a-439e-8398-41c4b10c9064', 'concept'::public.curated_course_node_type, 'Public health law, quarantine, isolation, reporting requirements, vaccination policy, and community trust', null, 3),
  ('863486a6-ed77-43fd-9505-82c7269cfc21', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'aa3e9bb9-6778-48f2-9c48-2394ad917a7b', 'subtopic'::public.curated_course_node_type, 'Population Health and Community Health Improvement', 'This subtopic shows students how health organizations manage outcomes for groups, not only individual encounters.', 1),
  ('aa4fc444-a224-44d7-b870-415bbf9aee7a', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '863486a6-ed77-43fd-9505-82c7269cfc21', 'concept'::public.curated_course_node_type, 'Population panels, registries, risk stratification, community health needs assessments, and population health management', null, 0),
  ('343bbf73-6f69-4e18-96f5-50793539d312', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '863486a6-ed77-43fd-9505-82c7269cfc21', 'concept'::public.curated_course_node_type, 'Screening rates, immunization rates, blood pressure control, diabetes control, readmissions, avoidable emergency visits', null, 1),
  ('72d29f9e-84f1-43c3-b26a-dc000e91c6ad', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '863486a6-ed77-43fd-9505-82c7269cfc21', 'concept'::public.curated_course_node_type, 'Community partnerships, coalitions, health education campaigns, social services integration, and place-based interventions', null, 2),
  ('c30bd841-68f8-453c-b378-1663a68ba3ee', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '863486a6-ed77-43fd-9505-82c7269cfc21', 'concept'::public.curated_course_node_type, 'Healthy People 2030 objectives, equity targets, community benefit, and evaluation of health promotion programs', null, 3),
  ('7400fa7a-f022-4819-a484-130414d2fdfc', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'aa3e9bb9-6778-48f2-9c48-2394ad917a7b', 'subtopic'::public.curated_course_node_type, 'Global Health and Comparative Health Systems', 'Students examine how health challenges cross borders and how systems differ in resources, governance, financing, and outcomes.', 2),
  ('0d51535d-3110-4011-8689-545a74af9629', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '7400fa7a-f022-4819-a484-130414d2fdfc', 'concept'::public.curated_course_node_type, 'Global burden of disease, pandemics, vaccination, antimicrobial resistance, maternal mortality, malnutrition, and climate health', null, 0),
  ('9c3d305f-6d53-48de-9978-dcacf06c01a9', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '7400fa7a-f022-4819-a484-130414d2fdfc', 'concept'::public.curated_course_node_type, 'WHO, global surveillance, humanitarian response, health security, health diplomacy, and universal health coverage', null, 1),
  ('2cc7bcf0-d5ab-4d08-8f19-a9604e8ab0ef', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '7400fa7a-f022-4819-a484-130414d2fdfc', 'concept'::public.curated_course_node_type, 'Low-resource settings, supply chains, workforce migration, essential medicines, and global health ethics', null, 2),
  ('83a82fe7-4f33-4a46-992c-874327623730', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '7400fa7a-f022-4819-a484-130414d2fdfc', 'concept'::public.curated_course_node_type, 'Comparative health systems, life expectancy, infant mortality, access, spending, quality, and equity indicators', null, 3),
  ('267d0708-cfcb-44ce-a8ba-4523bbe56106', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', null, 'topic'::public.curated_course_node_type, 'Evidence-Based Practice, Epidemiology, Biostatistics, and Research Literacy', 'Students do not need to become researchers in an introductory course, but they do need to recognize credible evidence. This section gives them the vocabulary to read claims carefully and ask better questions.', 12),
  ('333e3a61-6d29-42a0-a3c9-5ecca3927c31', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '267d0708-cfcb-44ce-a8ba-4523bbe56106', 'subtopic'::public.curated_course_node_type, 'Evidence-Based Practice and Clinical Questions', 'Students learn how professionals combine evidence, clinical expertise, and patient values in decision-making.', 0),
  ('50b32a40-c1da-4891-bc1a-77c8d34fc23b', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '333e3a61-6d29-42a0-a3c9-5ecca3927c31', 'concept'::public.curated_course_node_type, 'Evidence-based practice, clinical expertise, patient preferences, best available evidence, and shared decision-making', null, 0),
  ('fb1c7b39-ab54-4377-85d6-7cb47ddbfd9e', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '333e3a61-6d29-42a0-a3c9-5ecca3927c31', 'concept'::public.curated_course_node_type, 'PICO questions: patient/problem, intervention, comparison, outcome', null, 1),
  ('e7c9b588-b0c0-4040-9577-84095b1e5269', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '333e3a61-6d29-42a0-a3c9-5ecca3927c31', 'concept'::public.curated_course_node_type, 'Guidelines, systematic reviews, randomized controlled trials, cohort studies, case-control studies, qualitative studies, and expert opinion', null, 2),
  ('0f3c2b5d-15e7-4eef-943e-c722d05de214', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '333e3a61-6d29-42a0-a3c9-5ecca3927c31', 'concept'::public.curated_course_node_type, 'Clinical practice guidelines, USPSTF recommendations, strength of recommendation, quality of evidence, and applicability', null, 3),
  ('2d08beb9-ae42-44d9-981d-aa93d6b927a6', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '267d0708-cfcb-44ce-a8ba-4523bbe56106', 'subtopic'::public.curated_course_node_type, 'Epidemiology and Basic Study Design', 'This subtopic introduces the language used to describe disease patterns, risk, exposure, and population-level evidence.', 1),
  ('65110049-b4b0-4bf1-a82c-4cfa712f8569', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '2d08beb9-ae42-44d9-981d-aa93d6b927a6', 'concept'::public.curated_course_node_type, 'Incidence, prevalence, morbidity, mortality, case fatality, risk factor, exposure, outcome, confounding, and bias', null, 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('a4ef71bb-6eee-4608-b8cc-0c944d329400', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '2d08beb9-ae42-44d9-981d-aa93d6b927a6', 'concept'::public.curated_course_node_type, 'Cross-sectional, cohort, case-control, randomized trial, ecological, surveillance, and outbreak investigation designs', null, 1),
  ('fc8a204e-b3c0-4378-a62a-58dedb498c0e', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '2d08beb9-ae42-44d9-981d-aa93d6b927a6', 'concept'::public.curated_course_node_type, 'Relative risk, odds ratio, attributable risk, screening sensitivity, specificity, positive predictive value, and negative predictive value', null, 2),
  ('fce0b0ca-02b6-4ec1-8216-b48b2a9ed986', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '2d08beb9-ae42-44d9-981d-aa93d6b927a6', 'concept'::public.curated_course_node_type, 'Selection bias, information bias, recall bias, confounding, causation versus correlation, and generalizability', null, 3),
  ('ad5f0491-0b9a-48e8-b11e-3acfef62efc7', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '267d0708-cfcb-44ce-a8ba-4523bbe56106', 'subtopic'::public.curated_course_node_type, 'Biostatistics and Research Interpretation', 'Students build enough statistical literacy to understand common results without overclaiming what the numbers mean.', 2),
  ('b334b9eb-c239-40f7-b20e-56538ee9641e', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'ad5f0491-0b9a-48e8-b11e-3acfef62efc7', 'concept'::public.curated_course_node_type, 'Mean, median, standard deviation, confidence interval, p-value, statistical significance, clinical significance, and effect size', null, 0),
  ('a95a43f3-8c8e-4154-a09f-d7159de2eb94', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'ad5f0491-0b9a-48e8-b11e-3acfef62efc7', 'concept'::public.curated_course_node_type, 'Descriptive statistics, inferential statistics, sampling, randomization, power, Type I error, Type II error, and missing data', null, 1),
  ('cf9b9aec-648c-4806-bfce-03615263e954', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'ad5f0491-0b9a-48e8-b11e-3acfef62efc7', 'concept'::public.curated_course_node_type, 'Tables, graphs, forest plots, Kaplan-Meier curves, baseline characteristics, and subgroup analysis', null, 2),
  ('b90b8369-a511-40be-a936-2b74b6bc68be', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'ad5f0491-0b9a-48e8-b11e-3acfef62efc7', 'concept'::public.curated_course_node_type, 'Peer review, conflict of interest, reproducibility, preprints, predatory journals, and responsible use of research summaries', null, 3),
  ('48ded647-2c07-47e7-a323-1ad6e70dacd2', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', null, 'topic'::public.curated_course_node_type, 'Health Informatics, Telehealth, Digital Health, and Emerging Technologies', 'Healthcare work is increasingly digital. This section introduces students to the tools, data flows, opportunities, and risks that shape modern practice.', 13),
  ('30380d00-37a4-43eb-8e8e-6724dcf3511a', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '48ded647-2c07-47e7-a323-1ad6e70dacd2', 'subtopic'::public.curated_course_node_type, 'Health Informatics and Data Flow', 'Students learn how information systems support clinical work and where digital friction can create risk.', 0),
  ('9d24c69f-8bc8-41c9-be6c-c4a2b0c021a1', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '30380d00-37a4-43eb-8e8e-6724dcf3511a', 'concept'::public.curated_course_node_type, 'Electronic health records, computerized provider order entry, clinical decision support, e-prescribing, and patient portals', null, 0),
  ('b37f9389-8770-43ce-a2cb-ed01eb7b22a7', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '30380d00-37a4-43eb-8e8e-6724dcf3511a', 'concept'::public.curated_course_node_type, 'Interoperability, health information exchange, HL7, FHIR, data standards, interface engines, and information blocking', null, 1),
  ('2389cf4f-cb86-459c-b605-5f8784cd184b', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '30380d00-37a4-43eb-8e8e-6724dcf3511a', 'concept'::public.curated_course_node_type, 'Structured data, unstructured notes, registries, dashboards, alerts, reminders, and population health reports', null, 2),
  ('6f5b301c-532f-4ca7-971e-e2a081edb1dd', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '30380d00-37a4-43eb-8e8e-6724dcf3511a', 'concept'::public.curated_course_node_type, 'Data quality, duplicate records, alert fatigue, usability, workflow fit, and documentation burden', null, 3),
  ('d99af9d8-7997-42b0-ad3e-4910f2fbf88e', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '48ded647-2c07-47e7-a323-1ad6e70dacd2', 'subtopic'::public.curated_course_node_type, 'Telehealth, Remote Monitoring, and Digital Access', 'This subtopic helps students understand how virtual care expands access while creating new challenges for equity, privacy, and assessment.', 1),
  ('50b69af4-d644-4616-8bcd-e09e27e4cb1c', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'd99af9d8-7997-42b0-ad3e-4910f2fbf88e', 'concept'::public.curated_course_node_type, 'Synchronous telehealth, asynchronous messaging, remote patient monitoring, virtual triage, teleconsultation, and e-visits', null, 0),
  ('4622791f-d1ea-4f8b-aa50-6d5e427e56ca', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'd99af9d8-7997-42b0-ad3e-4910f2fbf88e', 'concept'::public.curated_course_node_type, 'Digital divide, broadband access, device access, language access, disability accommodations, and private space for visits', null, 1),
  ('abf42510-16fd-442c-be45-5490e09b9c16', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'd99af9d8-7997-42b0-ad3e-4910f2fbf88e', 'concept'::public.curated_course_node_type, 'Licensure across state lines, informed consent, telehealth etiquette, documentation, reimbursement, and emergency protocols', null, 2),
  ('6884fdbb-9f2f-4a47-a1de-65044ab3c607', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'd99af9d8-7997-42b0-ad3e-4910f2fbf88e', 'concept'::public.curated_course_node_type, 'Wearables, home blood pressure monitoring, glucose monitoring, pulse oximetry, and patient-generated health data', null, 3),
  ('8955db18-275c-422c-b51b-f599e635a3f3', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '48ded647-2c07-47e7-a323-1ad6e70dacd2', 'subtopic'::public.curated_course_node_type, 'AI, Analytics, and Emerging Technologies', 'Students develop a balanced view of innovation: digital tools can help, but require careful attention to bias, validation, and accountability.', 2),
  ('ea0c676b-e4c2-4012-99bd-7ab46c81ac94', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '8955db18-275c-422c-b51b-f599e635a3f3', 'concept'::public.curated_course_node_type, 'Predictive analytics, risk scores, clinical decision support, natural language processing, imaging AI, and workflow automation', null, 0),
  ('2961517f-244d-40ba-a67c-91af4eaf62d8', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '8955db18-275c-422c-b51b-f599e635a3f3', 'concept'::public.curated_course_node_type, 'Algorithmic bias, training data, validation, explainability, human oversight, false positives, false negatives, and accountability', null, 1),
  ('42f916ed-5191-45dd-bc8e-59538e67975b', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '8955db18-275c-422c-b51b-f599e635a3f3', 'concept'::public.curated_course_node_type, 'Precision medicine, genomics, mobile health apps, virtual reality, robotics, and smart devices', null, 2),
  ('af1f7a37-f399-40d4-8ad9-251ab4952939', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '8955db18-275c-422c-b51b-f599e635a3f3', 'concept'::public.curated_course_node_type, 'Cybersecurity, ransomware, phishing, downtime procedures, data governance, and ethical technology adoption', null, 3),
  ('7b5e1851-f9ff-49c2-a44c-3b3160bb84dc', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', null, 'topic'::public.curated_course_node_type, 'Career Planning, Self-Assessment, Professional Skills, Wellness, and Lifelong Learning', 'This section helps students turn exploration into action. They assess fit, plan experiences, build professional habits, and learn how to sustain themselves in demanding work.', 14),
  ('fce9994c-8437-4d52-bc1a-dba99d74cee0', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '7b5e1851-f9ff-49c2-a44c-3b3160bb84dc', 'subtopic'::public.curated_course_node_type, 'Self-Assessment and Career Fit', 'Students reflect on interests, strengths, constraints, values, and preferred work environments before committing to a path.', 0),
  ('41db1240-e855-4c3a-bb92-cd89e48de4c7', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'fce9994c-8437-4d52-bc1a-dba99d74cee0', 'concept'::public.curated_course_node_type, 'Values, skills, interests, personality, tolerance for uncertainty, emotional demands, schedule preferences, and financial constraints', null, 0),
  ('dce574e9-a397-4a18-aa0e-f7cccb9a71b7', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'fce9994c-8437-4d52-bc1a-dba99d74cee0', 'concept'::public.curated_course_node_type, 'Patient contact level, technical work, team intensity, autonomy, training length, debt, salary, and lifestyle considerations', null, 1),
  ('e16c14d1-711e-41be-a2a8-f19ff0da5cb5', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'fce9994c-8437-4d52-bc1a-dba99d74cee0', 'concept'::public.curated_course_node_type, 'Informational interviews, shadowing reflections, career comparison matrices, and decision journals', null, 2),
  ('7a807693-efdd-4a7c-8e37-5390ac9cea3e', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', 'fce9994c-8437-4d52-bc1a-dba99d74cee0', 'concept'::public.curated_course_node_type, 'Mission fit, service orientation, resilience, curiosity, cultural humility, and willingness to learn from feedback', null, 3),
  ('8e09ad58-90de-491d-8848-5c3ebef68fa7', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '7b5e1851-f9ff-49c2-a44c-3b3160bb84dc', 'subtopic'::public.curated_course_node_type, 'Professional Skills for Entry into Health Fields', 'This subtopic focuses on practical behaviors that help students succeed in coursework, clinical exposure, applications, and workplace settings.', 1),
  ('62d8eab9-401f-4684-976c-537ee87a0b2a', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '8e09ad58-90de-491d-8848-5c3ebef68fa7', 'concept'::public.curated_course_node_type, 'Professional email, resume or CV, cover letter, personal statement, interview preparation, networking, and mentorship', null, 0),
  ('ff2f1540-4420-4cf0-9e5a-603a69a8e87e', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '8e09ad58-90de-491d-8848-5c3ebef68fa7', 'concept'::public.curated_course_node_type, 'Time management, study strategies, teamwork, conflict resolution, feedback-seeking, reflective writing, and professionalism online', null, 1),
  ('c9a7058f-b2fe-4fb1-a117-17950c049975', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '8e09ad58-90de-491d-8848-5c3ebef68fa7', 'concept'::public.curated_course_node_type, 'CPR/BLS, first aid, infection control basics, medical terminology, privacy training, and workplace safety orientation', null, 2),
  ('d668bb40-1305-45cc-8e3a-115eec1ce592', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', '8e09ad58-90de-491d-8848-5c3ebef68fa7', 'concept'::public.curated_course_node_type, 'Service learning, volunteering, research experience, leadership roles, direct patient care hours, and documentation of experiences', null, 3),
