  ('dc569837-b47e-478a-9490-8406eded7217', 'd9e2b5c1-4a68-4f17-8b03-1c6e0a7d3f84', null, 'topic'::public.curated_course_node_type, 'Future of the Healthcare Workforce, Leadership, Advocacy, and Integrative Career Portfolio', 'The final section asks students to synthesize the course into a forward-looking professional plan. Students connect career exploration to workforce change, leadership, advocacy, and an evidence-backed portfolio.', 15),
